//! Commit and stash V1 (M4-7a) on temporary repositories: stash of selected files and
//! "Add to .gitignore" (with their undo / redo), recent messages, `commit.template`, and
//! commit signing with an SSH key generated by the test.

mod common;

use std::collections::BTreeMap;
use std::path::Path;
use std::process::Command;
use std::sync::Arc;

use common::{Fixture, RecordingSink};
use yaggui_lib::git::cli::GitCli;
use yaggui_lib::git::errors::ErrorCode;
use yaggui_lib::git::log::CommandLog;
use yaggui_lib::git::ops::types::{
    CommitRequest, GitignoreRuleKind, JournalOp, SignatureStatus, SigningFormat, StashPathsRequest,
};
use yaggui_lib::graph::types::{SignatureKind, signature_code};
use yaggui_lib::repo::RepoManager;
use yaggui_lib::store::Store;

struct Env {
    fx: Fixture,
    store: Arc<Store>,
    repos: Arc<RepoManager>,
    id: u32,
}

fn env(scenario: &str) -> Env {
    let fx = Fixture::new(scenario);
    fx.git(&["config", "user.name", "yaggui Tests"]);
    fx.git(&["config", "user.email", "tests@yaggui.dev"]);
    let sink = Arc::new(RecordingSink::default());
    let git = GitCli::new(Arc::new(CommandLog::new()), sink.clone())
        .with_env("GIT_CONFIG_NOSYSTEM", "1")
        .with_env(
            "GIT_CONFIG_GLOBAL",
            if cfg!(windows) { "NUL" } else { "/dev/null" },
        );
    let store = Arc::new(Store::open_in_memory().unwrap());
    let repos = Arc::new(
        RepoManager::new(Arc::new(git), store.clone(), sink)
            .without_watcher()
            .with_backup_dir(fx.root.join("backups")),
    );
    let id = repos.open(&fx.repo_str()).unwrap().id;
    Env {
        fx,
        store,
        repos,
        id,
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct State {
    head: String,
    index: String,
    worktree: BTreeMap<String, Vec<u8>>,
    stashes: String,
}

impl Env {
    fn out(&self, args: &[&str]) -> String {
        let out = Command::new("git")
            .args(args)
            .current_dir(self.fx.repo())
            .env("GIT_CONFIG_NOSYSTEM", "1")
            .env("GIT_CONFIG_GLOBAL", "/dev/null")
            .output()
            .unwrap();
        String::from_utf8(out.stdout).unwrap().trim().to_owned()
    }

    fn read(&self, path: &str) -> Option<String> {
        std::fs::read_to_string(self.fx.repo().join(path)).ok()
    }

    fn write(&self, path: &str, content: &str) {
        std::fs::write(self.fx.repo().join(path), content).unwrap();
    }

    fn state(&self) -> State {
        State {
            head: self.out(&["rev-parse", "HEAD"]),
            index: self.out(&["ls-files", "-s"]),
            worktree: worktree(&self.fx.repo()),
            stashes: self.out(&["stash", "list", "--format=%H %gs"]),
        }
    }

    /// Undo restores the state before `op`, redo the state after it, undo again the state
    /// before.
    fn round_trip(&self, op: impl FnOnce(&Env)) -> JournalOp {
        let before = self.state();
        op(self);
        let after = self.state();
        assert_ne!(before, after, "the operation changed nothing");
        let entry = self.repos.undo(self.id).unwrap();
        assert_eq!(self.state(), before, "undo of {:?}", entry.op);
        self.repos.redo(self.id).unwrap();
        assert_eq!(self.state(), after, "redo of {:?}", entry.op);
        self.repos.undo(self.id).unwrap();
        assert_eq!(self.state(), before, "second undo of {:?}", entry.op);
        entry.op
    }

    fn stash(&self, paths: &[&str], include_untracked: bool) -> Result<String, ErrorCode> {
        self.repos
            .stash_push_paths(
                self.id,
                StashPathsRequest {
                    paths: paths.iter().map(|p| (*p).to_owned()).collect(),
                    message: Some("partial".into()),
                    include_untracked,
                },
            )
            .map(|entry| entry.sha)
            .map_err(|e| e.code)
    }

    fn commit(&self, summary: &str, description: &str) -> Result<String, ErrorCode> {
        self.repos
            .commit(
                self.id,
                CommitRequest {
                    summary: summary.into(),
                    description: description.into(),
                    amend: false,
                    skip_hooks: true,
                },
            )
            .map(|r| r.sha)
            .map_err(|e| e.code)
    }
}

fn worktree(root: &Path) -> BTreeMap<String, Vec<u8>> {
    fn walk(root: &Path, dir: &Path, out: &mut BTreeMap<String, Vec<u8>>) {
        for entry in std::fs::read_dir(dir).unwrap() {
            let entry = entry.unwrap();
            let path = entry.path();
            if entry.file_name() == ".git" {
                continue;
            }
            if path.is_dir() {
                walk(root, &path, out);
            } else {
                let rel = path.strip_prefix(root).unwrap().to_string_lossy();
                out.insert(rel.replace('\\', "/"), std::fs::read(&path).unwrap());
            }
        }
    }
    let mut out = BTreeMap::new();
    walk(root, root, &mut out);
    out
}

// ---- Stash of selected files (F-182) -----------------------------------------------------

#[test]
fn stash_of_selected_files_leaves_the_others() {
    let env = env("dirty");
    let sha = env.stash(&["src.txt", "README.md"], false).unwrap();
    assert_eq!(env.out(&["rev-parse", "stash@{0}"]), sha);
    // Git records the whole index in a stash, even with a pathspec (`stash show` lists
    // staged.txt too); only the selected files are reverted.
    let shown = env.out(&["stash", "show", "--name-only", "stash@{0}"]);
    assert!(
        shown.contains("README.md") && shown.contains("src.txt"),
        "{shown}"
    );
    assert!(env.out(&["stash", "list"]).contains("On main: partial"));
    // Back to HEAD: no change left on the stashed files, the others untouched.
    let status = env.out(&["status", "--porcelain", "--untracked-files=all"]);
    assert_eq!(
        status,
        "A  staged.txt\n?? newdir/a.txt\n?? newdir/b.txt\n?? notes.txt"
    );
    // Popping it brings the changes back (staged.txt, recorded too, is already identical).
    env.fx.git(&["stash", "pop", "-q"]);
    assert_eq!(
        env.read("README.md").as_deref(),
        Some("# Fixture\nboth\nagain\n")
    );
    assert_eq!(env.read("src.txt").as_deref(), Some("line 1\nchanged\n"));
}

#[test]
fn stash_of_selected_files_round_trips() {
    let env = env("dirty");
    let op = env.round_trip(|env| {
        env.stash(&["README.md", "notes.txt"], true).unwrap();
        assert_eq!(env.read("notes.txt"), None);
    });
    let JournalOp::StashPush { paths, count, .. } = op else {
        panic!("{op:?}");
    };
    assert_eq!(
        (paths, count),
        (vec!["README.md".into(), "notes.txt".into()], 2)
    );
}

#[test]
fn untracked_files_are_only_stashed_on_request() {
    let env = env("dirty");
    // Alone, an untracked file is left out: nothing to stash.
    assert_eq!(
        env.stash(&["notes.txt"], false),
        Err(ErrorCode::NothingToStash)
    );
    // With a tracked one, only the tracked one goes.
    env.stash(&["notes.txt", "src.txt"], false).unwrap();
    let status = env.out(&["status", "--porcelain", "--", "src.txt", "README.md"]);
    assert_eq!(status, "MM README.md");
    assert_eq!(env.read("notes.txt").as_deref(), Some("notes\n"));
    env.stash(&["notes.txt"], true).unwrap();
    assert_eq!(env.read("notes.txt"), None);
    assert_eq!(env.out(&["stash", "list"]).lines().count(), 2);
}

#[test]
fn stash_of_selected_files_refuses_folders_and_clean_files() {
    let env = env("dirty");
    assert_eq!(
        env.stash(&["newdir"], true),
        Err(ErrorCode::InvalidArgument)
    );
    assert_eq!(env.stash(&["a.txt"], false), Err(ErrorCode::NothingToStash));
    assert_eq!(
        env.stash(&["../outside"], false),
        Err(ErrorCode::InvalidArgument)
    );
    assert_eq!(env.out(&["stash", "list"]), "");
}

#[test]
fn undo_of_a_stash_refuses_when_the_entry_is_gone() {
    let env = env("dirty");
    env.stash(&["src.txt"], false).unwrap();
    env.fx.git(&["stash", "drop", "-q"]);
    let before = env.state();
    let err = env.repos.undo(env.id).unwrap_err();
    assert_eq!(err.code, ErrorCode::UndoDiverged);
    assert_eq!(env.state(), before);
}

// ---- Add to .gitignore (F-069) --------------------------------------------------------

#[test]
fn gitignore_rule_is_appended_and_round_trips() {
    let env = env("dirty");
    let preview = env
        .repos
        .gitignore_preview(env.id, "newdir/a.txt", GitignoreRuleKind::Folder)
        .unwrap();
    assert_eq!(preview.rule, "/newdir/");
    assert!(!preview.exists);
    assert_eq!(preview.matches, ["newdir/a.txt", "newdir/b.txt"]);
    assert_eq!(preview.match_count, 2);
    let ext = env
        .repos
        .gitignore_preview(env.id, "notes.txt", GitignoreRuleKind::Extension)
        .unwrap();
    assert_eq!(ext.rule, "*.txt");
    assert_eq!(ext.match_count, 3);

    let op = env.round_trip(|env| {
        let rule = env
            .repos
            .add_to_gitignore(env.id, "notes.txt".into(), GitignoreRuleKind::File)
            .unwrap();
        assert_eq!(rule, "/notes.txt");
        assert_eq!(
            env.read(".gitignore").as_deref(),
            Some("build/\n/notes.txt\n")
        );
        let status = env.out(&["status", "--porcelain", "notes.txt"]);
        assert_eq!(status, "");
    });
    assert_eq!(
        op,
        JournalOp::Gitignore {
            rule: "/notes.txt".into()
        }
    );
}

#[test]
fn gitignore_is_created_and_not_duplicated() {
    let env = env("clean");
    env.write("debug.log", "x\n");
    env.repos
        .add_to_gitignore(env.id, "debug.log".into(), GitignoreRuleKind::Extension)
        .unwrap();
    assert_eq!(env.read(".gitignore").as_deref(), Some("*.log\n"));
    let history = env.repos.op_history(env.id).unwrap().len();
    env.repos
        .add_to_gitignore(env.id, "other.log".into(), GitignoreRuleKind::Extension)
        .unwrap();
    assert_eq!(env.read(".gitignore").as_deref(), Some("*.log\n"));
    assert_eq!(env.repos.op_history(env.id).unwrap().len(), history);
    let preview = env
        .repos
        .gitignore_preview(env.id, "debug.log", GitignoreRuleKind::Extension)
        .unwrap();
    assert!(preview.exists);
    // The undo of the creation deletes the file again.
    env.repos.undo(env.id).unwrap();
    assert_eq!(env.read(".gitignore"), None);
}

#[test]
fn gitignore_keeps_a_file_without_final_newline() {
    let env = env("clean");
    env.write(".gitignore", "target");
    env.write("x.tmp", "x\n");
    env.repos
        .add_to_gitignore(env.id, "x.tmp".into(), GitignoreRuleKind::File)
        .unwrap();
    assert_eq!(env.read(".gitignore").as_deref(), Some("target\n/x.tmp\n"));
}

// ---- Recent messages (F-068) and template (F-067) -------------------------------------

#[test]
fn committed_messages_are_remembered() {
    let env = env("dirty");
    env.commit("feat: first", "Body\n").unwrap();
    env.fx.git(&["add", "-A"]);
    env.commit("fix(ui): second", "").unwrap();
    let recent = env.store.recent_commit_messages(env.id).unwrap();
    let messages: Vec<&str> = recent.iter().map(|m| m.message.as_str()).collect();
    assert_eq!(messages, ["fix(ui): second", "feat: first\n\nBody"]);
    // A failed commit is not remembered.
    assert_eq!(env.commit("nothing", ""), Err(ErrorCode::NothingToCommit));
    assert_eq!(env.store.recent_commit_messages(env.id).unwrap().len(), 2);
}

#[test]
fn commit_settings_read_the_template_and_signing_config() {
    let env = env("clean");
    let settings = env.repos.commit_settings(env.id).unwrap();
    assert_eq!(settings.template, None);
    assert_eq!(settings.sign, None);

    env.write(
        "template.txt",
        "# Subject: type(scope): what\nfeat: \n\n# Why\nRefs #\n",
    );
    env.fx.git(&["config", "commit.template", "template.txt"]);
    env.fx.git(&["config", "commit.gpgsign", "true"]);
    env.fx.git(&["config", "gpg.format", "ssh"]);
    env.fx.git(&["config", "user.signingkey", "~/.ssh/id.pub"]);
    let settings = env.repos.commit_settings(env.id).unwrap();
    let template = settings.template.unwrap();
    assert_eq!(template.summary, "feat:");
    assert_eq!(template.description, "Refs #");
    assert_eq!(settings.sign, Some(SigningFormat::Ssh));
    assert_eq!(settings.signing_key.as_deref(), Some("~/.ssh/id.pub"));

    env.fx.git(&["config", "commit.template", "missing.txt"]);
    let settings = env.repos.commit_settings(env.id).unwrap();
    assert!(settings.template.is_none());
    assert!(settings.template_error.unwrap().contains("missing.txt"));
}

// ---- Signing (F-066) ------------------------------------------------------------------

/// Generates an ed25519 key in `dir` (`passphrase` may be empty). `None` without ssh-keygen.
fn ssh_key(dir: &Path, name: &str, passphrase: &str) -> Option<std::path::PathBuf> {
    let key = dir.join(name);
    let status = Command::new("ssh-keygen")
        .args([
            "-q",
            "-t",
            "ed25519",
            "-C",
            "yaggui-tests",
            "-N",
            passphrase,
            "-f",
        ])
        .arg(&key)
        .status()
        .ok()?;
    status.success().then_some(key)
}

#[test]
fn ssh_signed_commits_are_verified() {
    let env = env("dirty");
    let Some(key) = ssh_key(&env.fx.root, "signing", "") else {
        eprintln!("skipped: ssh-keygen (OpenSSH 8.2+) is not available");
        return;
    };
    let unsigned = env.out(&["rev-parse", "HEAD"]);
    env.fx.git(&["config", "gpg.format", "ssh"]);
    env.fx.git(&["config", "commit.gpgsign", "true"]);
    env.fx.git(&[
        "config",
        "user.signingkey",
        &key.with_extension("pub").to_string_lossy(),
    ]);
    let sha = env.commit("signed", "").unwrap();
    assert!(
        env.out(&["cat-file", "commit", &sha])
            .contains("-----BEGIN SSH SIGNATURE-----")
    );

    // No allowed signers file: signed, but nothing to check it against.
    let check = env.repos.verify_signature(env.id, &sha).unwrap();
    assert_eq!(check.status, SignatureStatus::Unverified);
    assert!(check.reason.unwrap().contains("allowedSignersFile"));

    let public = std::fs::read_to_string(key.with_extension("pub")).unwrap();
    let allowed = env.fx.root.join("allowed_signers");
    std::fs::write(&allowed, format!("tests@yaggui.dev {public}")).unwrap();
    env.fx.git(&[
        "config",
        "gpg.ssh.allowedSignersFile",
        &allowed.to_string_lossy(),
    ]);
    let check = env.repos.verify_signature(env.id, &sha).unwrap();
    assert_eq!(check.status, SignatureStatus::Verified);
    assert_eq!(check.signer.as_deref(), Some("tests@yaggui.dev"));
    assert!(check.key.unwrap().starts_with("SHA256:"));

    let check = env.repos.verify_signature(env.id, &unsigned).unwrap();
    assert_eq!(check.status, SignatureStatus::Unsigned);
    assert_eq!(
        env.repos.verify_signature(env.id, "zz").unwrap_err().code,
        ErrorCode::InvalidArgument
    );
}

#[test]
fn a_key_needing_its_passphrase_fails_with_a_typed_error() {
    let env = env("dirty");
    let Some(key) = ssh_key(&env.fx.root, "locked", "correct horse") else {
        eprintln!("skipped: ssh-keygen (OpenSSH 8.2+) is not available");
        return;
    };
    let head = env.out(&["rev-parse", "HEAD"]);
    env.fx.git(&["config", "gpg.format", "ssh"]);
    env.fx.git(&["config", "commit.gpgsign", "true"]);
    // The private key itself: ssh-keygen must decrypt it, and no agent holds it.
    env.fx
        .git(&["config", "user.signingkey", &key.to_string_lossy()]);
    let err = env
        .repos
        .commit(
            env.id,
            CommitRequest {
                summary: "locked".into(),
                description: String::new(),
                amend: false,
                skip_hooks: true,
            },
        )
        .unwrap_err();
    assert_eq!(err.code, ErrorCode::SigningFailed, "{err:?}");
    assert!(err.message.en.contains("passphrase"), "{err:?}");
    assert_eq!(env.out(&["rev-parse", "HEAD"]), head);

    // A missing key is a signing failure too, without the passphrase advice.
    env.fx
        .git(&["config", "user.signingkey", "/nonexistent/key.pub"]);
    let err = env.commit("missing key", "").unwrap_err();
    assert_eq!(err, ErrorCode::SigningFailed);
}

#[test]
fn graph_pages_carry_the_signature_kind() {
    let env = env("dirty");
    let Some(key) = ssh_key(&env.fx.root, "signing", "") else {
        eprintln!("skipped: ssh-keygen (OpenSSH 8.2+) is not available");
        return;
    };
    let unsigned = env.out(&["rev-parse", "HEAD"]);
    env.fx.git(&["config", "gpg.format", "ssh"]);
    env.fx.git(&["config", "commit.gpgsign", "true"]);
    env.fx.git(&[
        "config",
        "user.signingkey",
        &key.with_extension("pub").to_string_lossy(),
    ]);
    let signed = env.commit("signed", "").unwrap();

    let page = env.repos.graph_page(env.id, 0, 500).unwrap();
    assert_eq!(page.signatures.len(), page.shas.len());
    let code = |sha: &str| page.signatures[page.shas.iter().position(|s| s == sha).unwrap()];
    assert_eq!(code(&signed), signature_code::SSH);
    assert_eq!(code(&unsigned), signature_code::NONE);
    assert_eq!(
        page.signatures
            .iter()
            .filter(|&&c| c != signature_code::NONE)
            .count(),
        1
    );
    // Same reading as the commit detail.
    let detail = env.repos.commit_detail(env.id, &signed).unwrap();
    assert_eq!(detail.signature, Some(SignatureKind::Ssh));
    let detail = env.repos.commit_detail(env.id, &unsigned).unwrap();
    assert_eq!(detail.signature, None);
}
